+
+            // Lower all but the last body
+            for (int i = 0; i < bodies().size() - 1; i++) {
+                Block.Builder rhs = lhs.block();
+                lhs.transformBody(bodies().get(i), List.of(), loweringTransformer(inherited, (block, op) -> {
